{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In humans, lycopene systemic availability was approximately 2.6% after a 38-mg capsule dose, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In humans, lycopene systemic availability was only 0.17% after ingestion of tomato paste, indicating very low oral absorption for a highly lipophilic isoprenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In humans, lycopene absorption was 12.2% for all-trans and 16.6% for cis isomers, both below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In humans, only about 1.2% of a 6-mg lycopene dose dispersed in oil appeared in blood, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Phytoene showed an absolute oral bioavailability of 58.5 ± 18.9% in humans, above the 20% threshold, but this analogue has lower structural transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "All-trans lycopene bioavailability was 23.2 ± 8% in healthy humans, slightly above the 20% threshold, but lycopene results are highly formulation- and matrix-dependent.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest experimental analogues are carotenoid isoprenoids with low-to-moderate transferability. Most human lycopene measurements are below 20%, supporting low bioavailability, while the higher phytoene value is less transferable due to structural differences. The query's very high molecular weight, extreme lipophilicity, and lack of ionizable groups further favor poor oral absorption.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "Carotenoid analogues have limited structural transferability to the query's larger, more lipophilic scaffold.",
    "Lycopene bioavailability values are strongly influenced by food matrix, formulation, and isomer composition, so they may not reflect intrinsic absolute bioavailability.",
    "The phytoene high-bioavailability result comes from a small human compartmental-modeling study and may not generalize."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

